css:
/* Define custom properties for gradient colors */
@property --r {
  syntax: "<percentage>";
  initial-value: 0%;
  inherits: false;
}

@property --g {
  syntax: "<percentage>";
  initial-value: 0%;
  inherits: false;
}

/* Global styles */
html, body, div {
  display: grid;
}

html {
  min-height: 100vh;
}

body {
    width: 100vw;
    height: 100vh;
  background: #121212; /* Dark background for contrast */
}

/* Hide the SVG filter */
svg[aria-hidden=true][height="0"] {
  position: fixed;
}

/* Container for the animated gradient */
div {
  --border-width: 1em;
  --border-radius: 3em;
  --size: 25em;

  place-self: center;
  border: solid var(--border-width) gold;
  width: var(--size);
  aspect-ratio: 1;
  border-radius: var(--border-radius);
}

/* Animated gradient effect */
div::after {
  --gradient-colors: rgb(var(--r) var(--g) 0%),
                      rgb(calc(100% - var(--r)) calc(100% - var(--g)) 0%);

  margin: calc(-1 * var(--border-width));
  background: radial-gradient(var(--gradient-colors)),
              linear-gradient(var(--gradient-colors)),
              conic-gradient(at 0 100%, var(--gradient-colors) 25%);
  background-blend-mode: difference;
  clip-path: inset(3em round 1em);
  filter: url(#smoke) invert(1) saturate(2);
  content: "";

  /* Animation */
  animation: r 4.7s ease-in-out -1.93s infinite alternate,
             g 4.3s ease-in-out -2.37s infinite alternate;
}

/* Keyframes for gradient animation */
@keyframes r {
  to {
    --r: 100%;
  }
}

@keyframes g {
  to {
    --g: 100%;
  }
}
